fn f(x:int):
    return g(x)
fn g(x:int):
    return x

fn f():
    return g()
fn g():
    return f()

fn f(x:int)->int:
    if x==0:
        return 0
    return f(x-1)
assert(f(3)==0)

fn plus(x:int)->int:
    return x+1
fn apply(f:fn(int)->int,x:int)->int:
    return f(x)
assert(apply(plus,2)==3)

try:
    raise 'bad'
except err:
    print(err.code)
print(err)

fn f()->int:
    try:
        raise 'bad'
    except err:
        return 1
print(f())

try:
    raise 'a'
except err:
    for err in ['x']:
        raise

try:
    pass
except err:
    fn later():
        raise

fn f():
    try:
        pass
    finally:
        return

for i in range(2):
    try:
        pass
    finally:
        break

for i in range(2):
    try:
        pass
    finally:
        for j in range(2):
            continue

fn f()->int:
    try:
        return 1
    finally:
        print(1)
print(f())

fn f()->int:
    try:
        print(1)
    finally:
        raise 'x'

fn f()->int:
    try:
        print(1)
    finally:
        print(2)

fn f()->int:
    try:
        return 1
    except err:
        return 2
    finally:
        print(3)
print(f())
